def dedup_sources():
    """返回去重源清单 [(id, abs_path, scope, excludes)]。

    scope='kb'   → 知识库自身：递归 raw 全树的 *.md（首页 DOI）与 *.pdf
                   （但**跳过** excludes 里的前缀，默认见 KB_DEFAULT_EXCLUDES：
                    流水线产物 raw/notes、剪藏 raw/clippings —— 其首页 DOI 属别篇论文）
    scope='pdfs' → 普通文献目录：递归 *.pdf
    路径相对库根（库内）或绝对（库外），由 kb_lib.VAULT 判定。

    excludes：每个源可选 `exclude: [子路径, ...]`（相对该源 root 的 POSIX 前缀）。
    · 未写 `exclude` 键 ⇒ 该源用 KB_DEFAULT_EXCLUDES（仅对 scope='kb' 生效）。
    · 写 `exclude: []` ⇒ 完全关闭排除。
    · 写其它列表 ⇒ 覆盖默认。非 kb 源默认不排除（pdfs 目录不会被产物污染）。

    🔴 配置**唯一权威**：`dedup_sources` 段缺失/为空时才回退内置默认值，且**不静默**——
    兜底的库外目录写死在 E: 盘，与配置文件里的清单**可能不一致**
    （实测：配置里 chem_mater 已被用户注释掉，兜底里却还有），所以必须打印实际用到的路径，
    使用者才知道这次去重集是怎么来的。
    """
    cfg = K.load_lit_config()          # 配置坏 ⇒ 直接抛（见 cfg_paths）；不再吞掉换兜底数据
    srcs = cfg.get("dedup_sources") or []
    fell_back = False
    if not srcs:
        fell_back = True
        srcs = [{"id": k, "path": v, "scope": "pdfs"} for k, v in DEFAULT_PDF_SOURCES.items()]
        # 🔴 兜底 kb 源必须是 `raw` 而不是 `.`：`"."` 会被 os.walk 展开成**整个 vault**
        #    （projects/、tools/、_archive/ 全扫），既慢又会把非论文 md 的首页 DOI
        #    灌进去重集（去重集被污染 ⇒ 真实文献反而被跳过）。
        srcs.append({"id": "kb_raw", "path": "raw", "scope": "kb"})
    out = []
    for s in srcs:
        p = str(s.get("path") or "")
        if not p:
            continue
        p = p.replace("\\", "/")
        if not os.path.isabs(p):
            p = os.path.join(K.VAULT, *p.split("/"))
        scope = s.get("scope") or "pdfs"
        if "exclude" in s:
            raw_ex = s.get("exclude") or []
        elif scope == "kb":
            raw_ex = list(KB_DEFAULT_EXCLUDES)
        else:
            raw_ex = []
        excludes = tuple(norm_rel_exclude(e) for e in raw_ex if str(e).strip())
        out.append((s.get("id") or "?", p, scope, excludes))
    if fell_back:
        print("[warn] lit_config.yaml 的 dedup_sources 段缺失/为空 ⇒ 本次走**硬编码兜底**，"
              "去重集可能与配置不一致：")
        for sid, p, sc, _ex in out:
            print(f"         · {sid} ({sc}) = {p}")
        print("       修 lit_config.yaml 的 dedup_sources 段即可消除本告警。")
    # 🆕 2026-10-22：综述工程参考文献落点（projects/*/references）**自动**入去重集，
    #    与 kb_where 的「检索范围动态化」（坑 3）同一逻辑：新工程不必手改配置即被覆盖。
    #    用户约定：综述任务的参考文献放 `projects/<slug>/references/`（PDF + 提取 md 混放）。
    #    scope='kb' 扫 *.md 首页 DOI + *.pdf；excludes 传空——KB_DEFAULT_EXCLUDES 的
    #    排除前缀（raw/notes、raw/clippings）相对**源 root** 判定，对项目 references
    #    无意义，该目录也不存在"产物污染"问题。
    for _sid, _p, _sc in review_ref_sources():
        out.append((_sid, _p, _sc, ()))
    return out


def review_ref_sources():
    """projects/*/references 去重源（目录存在且含 PDF/md 才纳入）。"""
    found = []
    proj = os.path.join(K.VAULT, "projects")
    if not os.path.isdir(proj):
        return found
    for slug in sorted(os.listdir(proj)):
        refs = os.path.join(proj, slug, "references")
        if not os.path.isdir(refs):
            continue
        if not any(f.endswith((".pdf", ".md")) for f in os.listdir(refs)):
            continue
        found.append((f"proj_{slug}_refs", refs, "kb"))
    return found


def norm_rel_exclude(p):
    """把排除前缀归一为 POSIX 相对路径，去掉首尾斜杠、反斜杠、`./`。"""
    q = str(p).replace("\\", "/").strip()
    while q.startswith("./"):
        q = q[2:]
    return q.strip("/")


def _is_excluded(dp, root, excludes):
    """dp 是 os.walk 的当前目录（绝对），root 是源根（绝对）。
    返回 True 表示该目录应被剪枝（其下所有文件都不进去重集）。"""
    if not excludes:
        return False
    rel = os.path.relpath(dp, root).replace("\\", "/")
    if rel == ".":
        return False
    for ex in excludes:
        if rel == ex or rel.startswith(ex + "/"):
            return True
    return False


