def norm_doi(doi):
    """薄包装：DOI 归一统一走 kb_lib.norm_doi。

    🔴 本地旧实现只做 `lower() + rstrip(".")`：库内 15 条 DOI 尾部**粘连中文标点**
    （`…202411671。`）因此从未被清洗，同一篇在 PDF/Zotero/md 三个来源各成一条，
    永远合并不了。kb_lib 的版本会按 CJK/全角/空白截断再去尾标点。
    """
    return K.norm_doi(doi)


def doi_looks_complete(doi):
    """薄包装：完整 DOI 判定统一走 kb_lib.doi_looks_complete。

    保留本地同名函数（而非直接改名调用）是为了不破坏既有 selftest 引用与调用点。
    """
    return K.doi_looks_complete(doi)


def norm_title_key(t):
    return re.sub(r"[^a-z0-9一-鿿]+", "", (t or "").lower())


def total_key(doi, title):
    doi = norm_doi(doi)
    if doi and doi_looks_complete(doi):
        return "doi:" + doi
    tk = norm_title_key(title)
    return ("title:" + tk) if tk else None


def is_si_pdf(path):
    """补充材料不参与“这篇论文我已有了”的判定。

    SI 首页的 DOI 是**主文 DOI**；若把 `raw/pdf/si/<stem>.si.pdf` 计入目录，
    只拿到 SI、正文没下到的论文会被去重系统误判成“已在库”，从此不再尝试正文。
    （2026-10-26：ACS 浏览器兜底把 3 份 SI 当正文下载后，若刷新目录即会踩到。）
    """
    name = os.path.basename(path).lower()
    if ".si." in name:
        return True
    parent = os.path.dirname(os.path.abspath(path))
    return (os.path.basename(parent).lower() == "si"
            and os.path.basename(os.path.dirname(parent)).lower() == "pdf")


def extract_pdf_doi(path):
    """取 PDF 首页的完整 DOI；找不到返回 (None, None)。"""
    try:
        doc = fitz.open(path)
    except Exception:
        return None, None
    try:
        pg0 = doc[0].get_text() or ""
    except Exception:
        pg0 = ""
    finally:
        doc.close()
    d = first_clean_doi(pg0)
    return d, None


def first_clean_doi(text):
    for m in DOI_RE.finditer(text):
        d = norm_doi(m.group(0))
        if doi_looks_complete(d):
            return d
    return None


def name_to_title_key(fname):
    stem = Path(fname).stem
    stem = re.sub(r"\((\d+|legacy)\)|_v?\d+| - Copy|\s*\(1\)$", "", stem, flags=re.I)
    return norm_title_key(stem)


def raw_md_first_page_doi(text):
    """取 raw md 首页块的完整 DOI（论文自身），避免抓到文末参考文献。"""
    cut = text.split("<!-- page 2 -->")[0]
    return first_clean_doi(cut)


